                    if (_FWUpdatePlugin != null)
                    {
                        ret = _FWUpdatePlugin.RestartService().Result && ret;
                        writelog($"{nameof(SetServerURL)} Restart Service Ret:{ret}");
                    }
                }
            }
            writelog($"{nameof(SetServerURL)} done");
