        private void SystemEvents_DisplaySettingsChanged(object sender, EventArgs e)
        {
            writelog("[DeviceMangerPlugin] YYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYY");

            if (WTSFunction.IsYourProcessInActiveSession(Log))
            {
                writelog("[DeviceMangerPlugin] WTSFunction.IsYourProcessInActiveSession return True");

                _ = SystemEventsDisplaySettingsChangedAsync(new DebouncerArg()
                {
                    sender = sender,
                    eventArgs = e,
                });
            }
            else
                writelog("[DeviceMangerPlugin] WTSFunction.IsYourProcessInActiveSession return False");
        }

        private async Task SystemEventsDisplaySettingsChangedAsync(object _arg)
        {
            try
            {
                DebouncerArg arg = null;

                if (_arg != null)
                {
                    arg = (DebouncerArg)_arg;
                    writelog($"Receive DisplaySettingsChanged: {arg.sender}, e:{arg.eventArgs}, rescan monitor");
                }
                else
                    writelog($"Receive Re-GetMonitor or session changed, rescan monitor");

                if (displayInOut)
                {
                    if (_AllInfoMonitors != null)
                        _AllInfoMonitors.Clear();

                    if (_UpdateProgress != null && _FWUpdatePlugin != null)
                    {
                        writelog($"DisplaySettingsChanged: Rrconnect FWU eventv go");
                        _FWUpdatePlugin.ProgressUpdate_Notify -= show_fwProgressUpdateEvent;
                        _FWUpdatePlugin.ProgressUpdate_Notify += show_fwProgressUpdateEvent;
                        ProgressUpdate_Notify -= _UpdateProgress._FWUpdatePlugin_ProgressUpdate;
                        ProgressUpdate_Notify += _UpdateProgress._FWUpdatePlugin_ProgressUpdate;
                        writelog($"DisplaySettingsChanged: Rrconnect FWU eventv don");
                    }
                    writelog($"DisplaySettingsChanged: displayInOut is true");

                    if (isLetDisplayServiceIdle == true)
                    {
                        writelog("The idle state is true to drop display settings change event, need caller to unblock this param");
                        return;
                    }

                    //writelog("[DeviceMangerPlugin] SystemEvents_DisplaySettingsChanged() Bruce count Screen Length ...");
                    //Bruce 08-09 Added judgment that if the number of screens does not change, the screen orientation adjustment function will not be performed. (For example: PxP change will trigger this event, but the screen is not actually plugged in or out)
                    //bool displayDeviceNumChange = false;
                    //int AllScreens = Screen.AllScreens.Length;
                    //if (_lastScreenCount != AllScreens)
                    //{
                    //    displayDeviceNumChange = true;
                    //    _lastScreenCount = AllScreens;
                    //}
                    //writelog("[DeviceMangerPlugin] SystemEvents_DisplaySettingsChanged() Bruce count Screen Length finish ...");

                    try
                    {
                        writelog("[DeviceMangerPlugin] XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX");
                        writelog("[DeviceMangerPlugin] SystemEvents_DisplaySettingsChanged() Ready trigger cancel ...");

                        if (_ReGetcancellationTokenSource != null)
                        {
                            writelog("[DeviceMangerPlugin] SystemEvents_DisplaySettingsChanged() _ReGetcancellationTokenSource trigger cancel in XXX ...");
                            await _ReGetcancellationTokenSource.CancelAsync();

                            _ReGetcancellationTokenSource.Dispose();
                            _ReGetcancellationTokenSource = null;
                        }
                    }
                    catch (TaskCanceledException)
                    {
                        writelog("[DeviceMangerPlugin] I_SystemEvents_DisplaySettingsChanged() trigger cancel cancellation happened in XXX ...");

                        if (_ReGetcancellationTokenSource is not null)
                        {
                            _ReGetcancellationTokenSource.Dispose();
                            _ReGetcancellationTokenSource = null;
                        }
                    }
                    catch (OperationCanceledException)
                    {
                        writelog("[DeviceMangerPlugin] I_SystemEvents_DisplaySettingsChanged() trigger cancel cancellation happened in XXX ...");

                        if (_ReGetcancellationTokenSource is not null)
                        {
                            _ReGetcancellationTokenSource.Dispose();
                            _ReGetcancellationTokenSource = null;
                        }
                    }
                    catch (Exception ex)
                    {
                        writelog($"[DeviceMangerPlugin] I_SystemEvents_DisplaySettingsChanged() in XXX ...there is an exception-- ({ex.Message})");

                        if (_ReGetcancellationTokenSource is not null)
                        {
                            _ReGetcancellationTokenSource.Dispose();
                            _ReGetcancellationTokenSource = null;
                        }
                    }
                    finally
                    {
                        try
                        {
                            _ReGetcancellationTokenSource = new CancellationTokenSource();
                            var token = _ReGetcancellationTokenSource.Token;

                            writelog("[DeviceMangerPlugin] SystemEventsDisplaySettingsChangedAsync() into Re-GetDevices ...");

                            var NewMonitors = (await _DisplayManagerPlugin.Re_GetMonitors(token)).ToList();
                            _AllInfoMonitors = new(NewMonitors);

                            writelog($"[DeviceMangerPlugin] SystemEventsDisplaySettingsChangedAsync() get monitor count {NewMonitors.Count} ...");

                            var T1 = Task.Run(() => InitMonitorSettings(NewMonitors.ToList(), token), token);
                            //04/16 Jason Lin add InitDisplayData due to timing
                            _DisplayManagerPlugin.InitDisplayData(NewMonitors.ToList()).Wait(token);
                            var T2 = Task.Run(() => InitAllDisplayData(NewMonitors.ToList(), token), token);

                            // add @ 20250303 stephen
                            // modified @ 20250305 stephen : set count = -1 as a flag to avoid trigger ui reflash
                            if ((_arg != null) && (!token.IsCancellationRequested))
                            {
                                arg = (DebouncerArg)_arg;
                                show_displays_changed(arg.sender, new DisplaychangedEventArgs() { count = -1, monitors = NewMonitors });
                            }
                            // add @ 20250303 stephen

                            //NKVM monitor change
                            if (_NKVMPlugin != null && (!token.IsCancellationRequested))
                            {
                                writelog("[DeviceMangerPlugin] NKVM UpdateMonitorInfo ...");
                                _ = _NKVMPlugin.UpdateMonitorInfo(NewMonitors, token);
                            }

                            //Update display properties in display data
                            if (_DisplayManagerPlugin != null && (!token.IsCancellationRequested))
                            {
                                for (int i = 0; i < NewMonitors.Count; i++)
                                {
                                    if (token.IsCancellationRequested)
                                        break;

                                    writelog("[DeviceMangerPlugin]  GetDisplaySupportedProperties ...");
                                    _DisplayManagerPlugin.GetDisplaySupportedProperties(NewMonitors[i]).Wait(token);
                                }
                            }

                            if (!token.IsCancellationRequested)
                                ReviewAllMonitorToAvoidDuplicatedInfo();  //review monitor list to check duplicated data

                            //List<MonitorInfo> new_mo = new List<MonitorInfo>();
                            //if (NewMonitors.Count > 0)
                            //    new_mo.AddRange(NewMonitors);

                            writelog($"[DeviceManager] SystemEventsDisplaySettingsChangedAsync() Got event, monitor count {NewMonitors.Count}");

                            await Task.Run(() => { while ((T1.IsCompleted) || (token.IsCancellationRequested)) break; }, token);

                            if (!token.IsCancellationRequested)
                            {
                                if (NewMonitors.Count > 0)
                                    OnDeviceChanged(NewMonitors[0], null, DeviceChangedType.NotifyOnly, token, "DisplayChanged");//DeviceChangedType.Display_PlugIn);
                                else
                                    OnDeviceChanged(null, null, DeviceChangedType.NotifyOnly, token, "DisplayChanged");

                                writelog("[DeviceMangerPlugin] SystemEventsDisplaySettingsChangedAsync() OnDeviceChanged finish ...");

                                //Robert_Lin, 2024-9-9 Signal a DisplaySettingsChanged event through Agent
                                //Anyone who would like to receive this event, you can add below code: (refer to EAPlugin.cs)
                                // _agent.RegisterForEvent(AgentEventNames.DisplaySettingsChanged, DisplaySettingsChangedHandler);
                                //
                                // private void DisplaySettingsChangedHandler(object sender, EventManagerArgs e)
                                // {
                                //    your handler code
                                // }
                                //

                                if ((_agent != null) && (!token.IsCancellationRequested))
                                {
                                    _agent.RaiseEvent(AgentEventNames.DisplaySettingsChanged, this, new EventManagerArgs());
                                    writelog("[DeviceMangerPlugin] SystemEventsDisplaySettingsChangedAsync() _agent.RaiseEvent finish ...");
                                }

                                if ((NewMonitors.Count > 0) && (!token.IsCancellationRequested))
                                {
                                    _ = Task.Run(() =>
                                    {
                                        //Telementry Collection
                                        var rt = false;
                                        var DeviceTypeConnected_Function = new DeviceTypeConnected_Function();
                                        writelog("[DeviceMangerPlugin] [Telementry] Send Telementry for DeviceTypeConnected_Function...");
                                        rt = DeviceTypeConnected_Function.DeviceTypeConnected_Telementry(_TelementryScheduler, NewMonitors);
                                        if (rt)
                                            writelog("[DeviceMangerPlugin] [Telementry] Send Telementry for DeviceTypeConnected_Function Success ...");
                                        else
                                            writelog("[DeviceMangerPlugin] [Telementry] Send Telementry for DeviceTypeConnected_Function Fail ...");
                                    }, token);
                                }

                                ////1117 Bruce 不用自動旋轉把下兩行註解
                                //if (displayDeviceNumChange && NewMonitors.Count > 0)
                                //_DisplayManagerPlugin.SetDisplayOrientation(NewMonitors).Wait();
                                //writelog("[DeviceMangerPlugin] SystemEvents_DisplaySettingsChanged() SetDisplayOrientation finish ...");

                                if (!token.IsCancellationRequested)
                                {
                                    _ = _DisplayManagerPlugin.UpdateExistAlsConfig(NewMonitors.ToList());
                                    writelog("[DeviceMangerPlugin] SystemEventsDisplaySettingsChangedAsync() UpdateExistAlsConfig finish ...");
                                }

                                writelog($"[DeviceMangerPlugin] Toast Windows notification token.IsCancellationRequested: {token.IsCancellationRequested}");
                                if (NewMonitors != null && NewMonitors.Count > 0 && !token.IsCancellationRequested)
                                    _ = Task.Run(() => _disDevHelper?.CheckAndTriggerToastWhileMonitorPlugged(_millisecond, NewMonitors.ToList(), _SettingsPlugin));
                            }
                            else
                            {
                                writelog("[DeviceMangerPlugin] SystemEventsDisplaySettingsChangedAsync() cancel ...");
                            }

                            writelog("[DeviceMangerPlugin] SystemEventsDisplaySettingsChangedAsync() Re-GetDevices finish ...");
                        }
                        catch (TaskCanceledException)
                        {
                            writelog("[DeviceMangerPlugin] II_SystemEvents_DisplaySettingsChanged() trigger cancel cancellation happened ...");
                            //OnDeviceChanged(null, null, DeviceChangedType.NotifyOnly, CancellationToken.None, "DisplayChanged");
                        }
                        catch (OperationCanceledException)
                        {
                            writelog("[DeviceMangerPlugin] II_SystemEvents_DisplaySettingsChanged() trigger cancel cancellation happened ...");
                            //OnDeviceChanged(null, null, DeviceChangedType.NotifyOnly, CancellationToken.None, "DisplayChanged");
                        }
                        catch (Exception ex)
                        {
                            // Failed to complete due to e exception
                            writelog($"[DeviceMangerPlugin] II_SystemEvents_DisplaySettingsChanged() ...there is an exception-- ({ex.Message})");
                            //OnDeviceChanged(null, null, DeviceChangedType.NotifyOnly, CancellationToken.None, "DisplayChanged");
                        }
                    }
                }
                else//Add by Bruce
                {
                    if (_arg != null)
                        writelog($"DisplaySettingsChanged: {arg.sender}, e:{arg.eventArgs}, By pass.");
                    else
                        writelog($"GetMonitor, By pass.");

                    displayInOut = true;
                }
            }
            catch (Exception x)
            {
                writelog($"[DeviceMangerPlugin] III_SystemEvents_DisplaySettingsChanged()...there is an exception-- ({x.Message})");
            }
        }

