        protected virtual void OnDeviceChanged(MonitorInfo mo, DeviceInfo di, DeviceChangedType type, CancellationToken token, string changedProperty = "")
        {
            writelog($"[DeviceMangerPlugin] OnDeviceChanged {type.ToString()}, {changedProperty}");
            DeviceChangedEventArgs _EventArgs = new DeviceChangedEventArgs();
            if (_UpdateProgress != null && _FWUpdatePlugin != null)
            {
                writelog($"OnDeviceChanged: Rrconnect FWU eventv go");
                _FWUpdatePlugin.ProgressUpdate_Notify -= show_fwProgressUpdateEvent;
                _FWUpdatePlugin.ProgressUpdate_Notify += show_fwProgressUpdateEvent;
                ProgressUpdate_Notify -= _UpdateProgress._FWUpdatePlugin_ProgressUpdate;
                ProgressUpdate_Notify += _UpdateProgress._FWUpdatePlugin_ProgressUpdate;
                writelog($"OnDeviceChanged: Rrconnect FWU eventv don");
            }

            if (type == DeviceChangedType.NotifyOnly)
            {
                //writelog("[OnDeviceChanged] Notify event to registers");
                //Task.Run(() => updateALSwithAllMonitors());
            }
            else
            {
                // << 240715 revised by Hess to handle dongle emply
                //if (di == null)
                //{
                //    writelog("[OnDeviceChanged] null pheripherals device info object!");
                //    return;
                //}
                _EventArgs.deviceID = di?.ID.ToString() ?? "";// temp unique guid;
                                                              // >>
            }

            if (changedProperty != "DisplayChanged" && type == DeviceChangedType.Peripherals_PlugIn)
            {
                CheckDeviceFirstTimesToConnect(mo, di);
                writelog($"OnDeviceChanged: CheckDeviceFirstTimesToConnect out ... ");
            }

            if (type == DeviceChangedType.Display_UnPlug)//Bruce 0224 add. If the dock has multiple connections, send a Display event to force the UI to return to home.
            {
                type = DeviceChangedType.NotifyOnly;
                changedProperty = "DisplayChanged";
            }

            writelog("[DeviceMangerPlugin] DeviceMangerPlugin Notify UI Update in OnDeviceChanged ...");

            _EventArgs.type = type;
            _EventArgs.device_display = mo;
            _EventArgs.device_peripherals = di;
            _EventArgs.changedProperty = changedProperty;
            EventHandler<DeviceChangedEventArgs> handler = DeviceChanged;
            if (handler != null)
                _ = Task.Run(() => handler.Invoke(this, _EventArgs), token);

            if (changedProperty.ToLower().Contains("add"))
            {
                //else
                //{
                //    _NKVMPlugin.MonitorPlug();
                //    SupportedNKVMMonitors();
                //}

                //0909 Bruce move to add and remove
                //var thread = new Thread(() =>
                //{
                //    //CheckUpdate();
                //    CheckUODFWUInfoPackage(true);
                //});
                //thread.Start();
                Task.Run(() =>
                {
                    //CheckUpdate();
                    CheckUODFWUInfoPackage(true);
                });
            }
            //else if (changedProperty.ToLower().Contains("remove"))
            //{
            //}
            else if ((string.Compare(changedProperty, "DisplayChanged", true) == 0))
            {
                //if (_NKVMPlugin != null)
                //{
                //    _NKVMPlugin.UpdateMonitorInfo(_AllInfoMonitors, token);
                //}
                DisplayFWCheck();

                //Dean20250327 move icc check from OnDeviceChanged to here
                Task.Run(() =>
                {
                    try
                    {
                        List<MonitorInfo> tmp = new List<MonitorInfo>();
                        tmp.AddRange(_AllInfoMonitors);//when processing the icc, the list may change cause exception
                        foreach (var monitor in tmp)
                        {
                            if (_ColorPresetPlugin != null)//Bruce 02/10 added display In/Out to check icm
                            {
                                writelog($"[OnDeviceChanged]: _ColorPresetPlugin.DownloadICCData go ({_AllInfoMonitors.Count})");

                                _ColorPresetPlugin.DownloadICCData(monitor.modelName, monitor.DisplayName, true, "", true).Wait();
                                writelog($"[OnDeviceChanged]: _ColorPresetPlugin.DownloadICCData done");
                            }
                            else
                                writelog($"[OnDeviceChanged]: _ColorPresetPlugin is null, skip DownloadICCData({monitor.modelName})");
                        }
                    }
                    catch (Exception ex)
                    {
                        writelog($"[OnDeviceChanged]: _ColorPresetPlugin.DownloadICCData exception: {ex.Message}");
                    }
                });

                //for USB KVM auto switch kb ms
                foreach (var monitor in _AllInfoMonitors)
                {
                    if (monitor.CapabilityDic.ContainsKey("E9") && monitor.CapabilityDic.ContainsKey("E7"))
                        Task.Run(() => updatePBPModeStatus(monitor, "E9")).ConfigureAwait(false);
                    //if (_ColorPresetPlugin != null)//Bruce 02/10 added display In/Out to check icm
                    //{
                    //    writelog($"OnDeviceChanged: _ColorPresetPlugin.DownloadICCData go");
                    //    _ColorPresetPlugin.DownloadICCData(monitor, true).Wait();
                    //    writelog($"OnDeviceChanged: _ColorPresetPlugin.DownloadICCData done");
                    //}
                    //else
                    //    writelog($"OnDeviceChanged: _ColorPresetPlugin is null, skip DownloadICCData({monitor.modelName})");
                }
            }
        }

        /// <summary>
        /// First plugin device, check if need to launch DDPM
        /// </summary>
        /// <param name="mo"></param>
        /// <param name="di"></param>
        private void CheckDeviceFirstTimesToConnect(MonitorInfo mo, DeviceInfo di)
        {
            try
            {
                if (_DisplayManagerPlugin == null)
                {
                    writelog($"CheckDeviceFirstTimesToConnect _DisplayManagerPlugin NULL ... ");
                    return;
                }
                if (_DisplayManagerPlugin.GetIsDDPMLaunchNow().Result)
                {
                    writelog($"CheckDeviceFirstTimesToConnect isDDPMlaunch true ... ");
                    return;
                }
                if (di == null)
                {
                    writelog($"CheckDeviceFirstTimesToConnect DeviceInfo null ... ");
                    return;
                }
                bool result = false;
                object regValue;

                string UserId = WTSFunction.DirectGetUserID(Log);

                if (UserId == null)
                {
                    writelog($"CheckDeviceFirstTimesToConnect UserId null ... ");
                    return;
                }

                string regPath = $@"SOFTWARE\Dell\Dell Display And Peripheral Manager\UserSettings\Local\{UserId}";
                string regKey = $"IsFirstTimeWalkThroughDone_com.dell.DPM.Plugin.LogicalDevice.{di.ModelNumber}";
                string ddpmExePath = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), @"Dell\Dell Display and Peripheral Manager\DDPM.exe");
                //string ddpmExePath = @"D:\\NEW\DDPM\DDPM.UI\\bin\\net8.0-windows10.0.19041.0\\DDPM.exe";

                if (!File.Exists(ddpmExePath))
                {
                    writelog($"CheckDeviceFirstTimesToConnect File not found at path: {ddpmExePath} ... ");
                    return;
                }

                regValue = ReadRegistryData(DDPM.SA.Common.Settings.RegistryHive.LocalMachine, regPath, regKey).Result;
                //Trace.WriteLine($"regValue {regValue.ToString()}");
                // mean null or "" or is false, add to the queue and set it to true
                if (regValue == null || (regValue is string strValue && string.IsNullOrEmpty(strValue)))
                {
                    _DisplayManagerPlugin.LauncDDPM(UserId, ddpmExePath); //
                    writelog($"CheckDeviceFirstTimesToConnect LauncDDPM : UserId : {UserId}, ddpmExePath : {ddpmExePath} END ... ");
                }
                else
                {
                    writelog($"CheckDeviceFirstTimesToConnect ReadRegistryData UserId : {UserId}, find ModelNumber : {di.ModelNumber}");
                }
            }
            catch (Exception ex)
            {
                writelog($"CheckDeviceFirstTimesToConnect Exception : {ex.Message}");
            }
        }

        private void show_displays(object sender, VCPchangedEventArgs e)
        {
            writelog("Receive VcpChanged Event Notify from DisplayManagerPlugin");
            writelog("Send out VcpChanged Event Notify from DeviceMangerPlugin");

            VCPchangedEventArgs _VCPchangedEventArgs = new VCPchangedEventArgs();
            _VCPchangedEventArgs.vcpcode = e.vcpcode;
            _VCPchangedEventArgs.value = e.value;
            //0607 Bruce 因VCPChange事件需要取得螢幕資訊故請Jarvis新增這段變數 代為新增
            _VCPchangedEventArgs.monitor = e.monitor;
#if DEBUG
            Debug.WriteLine($"show_display=>monitor:{e.monitor.modelName}=={e.vcpcode}:{e.value}");
            Console.WriteLine($"show_display=>monitor:{e.monitor.modelName}=={e.vcpcode}:{e.value}");
#endif
            //1106 add PBP mode status
            Task.Run(() => updatePBPModeStatus(e.monitor, e.vcpcode)).ConfigureAwait(false);
            //Jason add USB change
            if (e.vcpcode.Equals("E7") &&
                _DisplayManagerPlugin != null)
            {
                Dictionary<string, InputInfo> inputSourceList = GetInputSourcelist(e.monitor).Result;
                foreach (var input in inputSourceList)
                {
                    string usbUpstream = GetUSBUpstream(e.monitor, input.Key).Result;
                    //Update USBKVM
                    if (GetOnUSBKVM(e.monitor).Result)
                    {
                        List<DDPMMonitorSettings> settings = _SettingsPlugin.ReloadMonitorSettings(e.monitor.modelName).Result;
                        if (settings != null)
                        {
                            //get monitor setting
                            DDPMMonitorSettings monitorSetting = settings.Find(x => x.ServiceTag == e.monitor.edid.ServiceTag);
                            if (monitorSetting != null)
                            {
                                try
                                {
                                    if (!string.IsNullOrEmpty(monitorSetting.KVM.strUSBKVMPCsList))
                                    {
                                        Dictionary<string, PCsInfo> USBKVMPCsList = USBKVMPCsListDeserialize(monitorSetting.KVM.strUSBKVMPCsList);
                                        if (USBKVMPCsList != null)
                                        {
                                            if (USBKVMPCsList.Count != 0)
                                            {
                                                foreach (var pc in USBKVMPCsList)
                                                {
                                                    if (!string.IsNullOrEmpty(pc.Key) &&
                                                        pc.Value != null &&
                                                        pc.Value.InputType == input.Key)
                                                    {
                                                        pc.Value.USBUpstream = usbUpstream;
                                                        bool b = SetUSBKVMPCsList(e.monitor, USBKVMPCsList).Result;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        else
                                        {
                                            writelog("[show_displays] USBKVMPCsList is null");
                                        }
                                    }
                                }
                                catch (Exception ex)
                                {
                                    writelog($"[show_displays]SetUSBKVMPCsList Exception {ex.Message.ToString()}");
                                }
                            }
                            else
                            {
                                writelog("[show_displays] monitorSetting is null");
                            }
                        }
                        else
                        {
                            writelog("[show_displays] settings is null");
                        }
                    }
                }
            }
            OnVCPchanged(_VCPchangedEventArgs);
        }

