        private void InitAllDisplayData(List<MonitorInfo> AllMonitors, CancellationToken cancellationToken)
        {
            //InitMonitorSettings();
            try
            {
                if (AllMonitors != null && AllMonitors.Count > 0)
                {
                    //_DisplayManagerPlugin.InitDisplayData(AllMonitors).Wait(cancellationToken);

                    for (int i = 0; ((i < AllMonitors.Count) && (!cancellationToken.IsCancellationRequested)); i++)
                    {
                        MonitorInfo info = AllMonitors[i];

                        _ = _DisplayManagerPlugin.GetVCPCapability(info, 0xE9);

                        if (info.CapabilityString.Contains("F4"))
                            _ = _DisplayManagerPlugin.GetGamingProperties_SupportedList(info);

                        _DisplayManagerPlugin.GetDisplayPropertiesInfo(info).Wait(cancellationToken);

                        if (!cancellationToken.IsCancellationRequested)
                            _ = _DisplayManagerPlugin.GetVCPCapability(info, "colorpreset");

                        _DisplayManagerPlugin.GetUSBUpstreamList(info).Wait(cancellationToken);

                        if (!cancellationToken.IsCancellationRequested)
                            _ = _DisplayManagerPlugin.GetAllUSBUpstream(info);
                    }

                    if (!cancellationToken.IsCancellationRequested)
                        UpdateHotkeyInfo(cancellationToken);
                }
            }
            catch (Exception ex)
            {
                writelog($"InitAllDisplayData exception : {ex.ToString()}");
            }
        }

        private void show_displays_changed(object sender, DisplaychangedEventArgs e)
        {
            // add @ 20250305 stephen, if e.count == -1 means only catch a display changed event, not trigger from vcp core
            if (e.count < 0)
            {
                writelog($"Receive Displaychanged Event Notify from DisplayManagerPlugin, but count < 0 ({e.count}) *****");
                OnDisplaychanged(e);
                return;
            }
            // add @ 20250305 stephen

            //if GetMonitors() already return right list, this function won't be called
            //it means if vcp core find the different monitor then this call will be triggered
            writelog("Receive Displaychanged Event Notify from DisplayManagerPlugin");

            _AllInfoMonitors = (e.monitors).ToList();

            writelog($"monitor count {e.monitors.Count} ...");

            InitMonitorSettings((e.monitors).ToList(), CancellationToken.None);
            //04/16 Jason Lin add InitDisplayData due to timing
            _DisplayManagerPlugin.InitDisplayData((e.monitors).ToList()).Wait(CancellationToken.None);
            Task.Run(() => InitAllDisplayData((e.monitors).ToList(), CancellationToken.None));

            DisplaychangedEventArgs _displaychangedEventArgs = new DisplaychangedEventArgs();
            _displaychangedEventArgs.count = e.count;
            _displaychangedEventArgs.monitors = e.monitors.ToList();

            writelog("Send out Displaychanged Event Notify from DeviceMangerPlugin");
            OnDisplaychanged(_displaychangedEventArgs);

            if (e.monitors.Count > 0)
            {
                Task.Run(() =>
                {
                    //Telementry Collection
                    var rt = false;
                    var DeviceTypeConnected_Function = new DeviceTypeConnected_Function();
                    writelog("[DeviceMangerPlugin] [Telementry] Send Telementry for DeviceTypeConnected_Function...");
                    rt = DeviceTypeConnected_Function.DeviceTypeConnected_Telementry(_TelementryScheduler, e.monitors);
                    if (rt)
                        writelog("[DeviceMangerPlugin] [Telementry] Send Telementry for DeviceTypeConnected_Function Success ...");
                    else
                        writelog("[DeviceMangerPlugin] [Telementry] Send Telementry for DeviceTypeConnected_Function Fail ...");
                }).ConfigureAwait(false);
            }
        }

