        private bool _screenSaver = false;

        private void OnPowerNapTimedRaise(object sender, ElapsedEventArgs e)
        {
            bool screenSaverStatus = JobQueue.GetScreensaverCurrentStatus(JobQueue.SPI_GETSCREENSAVERRUNNING);
            if (screenSaverStatus)
            {
                if (!_screenSaver)
                {
                    writelog($"powerNap screenSaver Status {screenSaverStatus}");
                    List<PowerNapSetting> read = ReadPowerNapSettings().Result;
                    List<JobInfo> allJobs = new List<JobInfo>();
                    foreach (PowerNapSetting setting in read)
                    {
                        MonitorInfo monitorInfo = _AllInfoMonitors.Find(x => x.modelName.Equals(setting.ModelName) && x.edid.ServiceTag.Equals(setting.ServiceTag));
                        if (monitorInfo != null &&
                            setting.Status)
                        {
                            switch (setting.RunType)
                            {
                                case PowerNapType.ReduceBrightness:
                                    allJobs.Add(new JobInfo(1000, monitorInfo, new object[] { true }, PowerNapReduceBrightness));
                                    //_powerNapJobQueue.Enqueue(new JobInfo(monitorInfo, new object[] { true }, PowerNapReduceBrightness));
                                    Debug.WriteLine($"{setting.ModelName}:{setting.ServiceTag} ReduceBrightness - Enqueue:true");
                                    writelog($"powerNap [{setting.ModelName}:{setting.ServiceTag}] ReduceBrightness - Enqueue:true");
                                    break;

                                case PowerNapType.SleepIfRunning:
                                    allJobs.Add(new JobInfo(1000, monitorInfo, new object[] { true }, PowerNapSuspendMonitor));
                                    //_powerNapJobQueue.Enqueue(new JobInfo(monitorInfo, new object[] { true }, PowerNapSuspendMonitor));
                                    Debug.WriteLine($"{setting.ModelName}:{setting.ServiceTag} SleepIfRunning - Enqueue:true");
                                    writelog($"powerNap [{setting.ModelName}:{setting.ServiceTag}] SleepIfRunning - Enqueue:true");
                                    break;

                                case PowerNapType.Off:
                                    break;
                            }
                        }
                    }
                    List<JobInfo> jobInfos = allJobs.Distinct().ToList();
                    foreach (JobInfo jobInfo in jobInfos)
                    {
                        _powerNapJobQueue.Enqueue(jobInfo);
                    }
                    _screenSaver = true;
                }
            }
            else
            {
                if (_screenSaver)
                {
                    writelog($"powerNap screenSaver Status {screenSaverStatus}");
                    List<PowerNapSetting> read = ReadPowerNapSettings().Result;
                    List<JobInfo> allJobs = new List<JobInfo>();
                    foreach (PowerNapSetting setting in read)
                    {
                        MonitorInfo monitorInfo = _AllInfoMonitors.Find(x => x.edid.ServiceTag.Equals(setting.ServiceTag) && x.modelName.Equals(setting.ModelName));
                        if (monitorInfo != null && setting.Status)
                        {
                            switch (setting.RunType)
                            {
                                case PowerNapType.ReduceBrightness:
                                    allJobs.Add(new JobInfo(1000, monitorInfo, new object[] { false }, PowerNapReduceBrightness));
                                    //_powerNapJobQueue.Enqueue(new JobInfo(monitorInfo, new object[] { false }, PowerNapReduceBrightness));
                                    Debug.WriteLine($"{setting.ModelName}:{setting.ServiceTag} ReduceBrightness - Enqueue:false");
                                    writelog($"powerNap [{setting.ModelName}:{setting.ServiceTag}] ReduceBrightness - Enqueue:false");
                                    break;

                                case PowerNapType.SleepIfRunning:
                                    allJobs.Add(new JobInfo(1000, monitorInfo, new object[] { false }, PowerNapSuspendMonitor));
                                    //_powerNapJobQueue.Enqueue(new JobInfo(monitorInfo, new object[] { false }, PowerNapSuspendMonitor));
                                    Debug.WriteLine($"{setting.ModelName}:{setting.ServiceTag} SleepIfRunning - Enqueue:false");
                                    writelog($"powerNap [{setting.ModelName}:{setting.ServiceTag}] SleepIfRunning - Enqueue:false");
                                    break;

                                case PowerNapType.Off:
                                    break;
                            }
                        }
                    }
                    List<JobInfo> jobInfos = allJobs.Distinct().ToList();
                    foreach (JobInfo jobInfo in jobInfos)
                    {
                        _powerNapJobQueue.Enqueue(jobInfo);
                    }
                    _screenSaver = false;
                }
            }
        }

        public void PowerNapReduceBrightness(MonitorInfo monitorInfo, Object[] param)
        {
            // ReduceBrightness
            //SetVCPCapability(monitorInfo, 0xE0, 1);
            bool cs = (bool)param[0];
            ObjGetVCP rc = new ObjGetVCP();
            string capability = monitorInfo.CapabilityString;
            if (capability.Contains("E0("))
            {
                int getvalue = 0;
                string[] ss = capability.Split("E0(");
                ss = ss[1].Split(")");
                ss = ss[0].Split(" ");
                if (ss[0] == "03" || ss[0] == "0F")
                {
                    rc = GetVCPCapability(monitorInfo, 0xE0).Result;
                    if (int.TryParse(rc.value.ToString(), out int crtValue))
                    {
                        getvalue = (crtValue & 0x0c);
                        writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] ,OdeValue={rc.value.ToString()}, NewValue ={getvalue}");
                    }
                    else
                    {
                        writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] ,parse currentValue ={rc.value.ToString()} fail.");
                    }
                }
                else if (ss[0] == "13")
                {
                    rc = GetVCPCapability(monitorInfo, 0xE0).Result;
                    if (int.TryParse(rc.value.ToString(), out int crtValue))
                    {
                        getvalue = (crtValue & 0x1c);
                        writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] ,OdeValue={rc.value.ToString()}, NewValue ={getvalue}");
                    }
                    else
                    {
                        writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] ,parse currentValue ={rc.value.ToString()} fail.");
                    }
                }

                if (cs)
                {
                    bool ret = SetVCPCapability(monitorInfo, 0xE0, (1 | (uint)getvalue)).Result;
                    writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] ON,[0xE0,r={getvalue},w={1 | (uint)getvalue}] and setVcp: " + (ret ? "success" : "fail"));
                }
                else
                {
                    bool ret = SetVCPCapability(monitorInfo, 0xE0, (/*0 |*/ (uint)getvalue)).Result;
                    writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] OFF,[0xE0,r={getvalue},w={(uint)getvalue}] and setVcp: " + (ret ? "success" : "fail"));
                }
            }
            else
            {
                if (cs)
                {
                    bool ret = SetVCPCapability(monitorInfo, 0xE0, 1).Result;
                    writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] ON,[0xE0,w=1] and setVcp: " + (ret ? "success" : "fail"));
                }
                else
                {
                    bool ret = SetVCPCapability(monitorInfo, 0xE0, 0).Result;
                    writelog($"PowerNap ReduceBrightness:[{monitorInfo.edid.ModelName}:{monitorInfo.edid.SerialNumber}] OFF,[0xE0,w=0] and setVcp: " + (ret ? "success" : "fail"));
                }
            }
        }

