        private List<VCPCode> GetAllVCPcode(MonitorInfo monitorInfo)
        {
            List<VCPCode> vcps = new List<VCPCode>();
            foreach (string key in monitorInfo.CapabilityDic.Keys)
            {
                if (Int32.TryParse(key, System.Globalization.NumberStyles.HexNumber, CultureInfo.InvariantCulture, out int vcpCode))
                {
                    VCPCode vcp = new VCPCode(vcpCode, null);
                    vcps.Add(vcp);
                }
                else
                {
                    // Log the error or handle it as needed
                    writelog($"Failed to parse VCP code: {key}");
                }
            }
            return vcps;
        }

        private void SetVCPSequence(MonitorInfo monitorInfo, ImpVCPSequence impVCPSequence, List<VCPCode> vcps)
        {
            writelog("[SetVCPSequence] SetVCPSequence ... in ");
            try
            {
                if (impVCPSequence != null)
                {
                    if (vcps.Count != 0)
                    {
                        foreach (var item in vcps)
                        {
                            writelog($"[SetVCPSequence] Code: {item.Code}, Value:{item.Value}");
                            Trace.WriteLine($"Code: {item.Code}, Value:{item.Value}");
                        }

                        ImportVCP importVCP = new ImportVCP();
                        foreach (int code in importVCP.ImportVCPSequence)
                        {
                            if (vcps.Exists(x => x.Code == code))
                            {
                                VCPCode vcp = vcps.Find(x => x.Code == code);
                                ObjGetVCP objGetVCP = new ObjGetVCP();
                                objGetVCP = GetVCPCapability(monitorInfo, (byte)vcp.Code).Result;
                                if (objGetVCP.result && (int)(uint)objGetVCP.value != (int)vcp.Value[0])
                                {
                                    writelog("[SetVCPSequence] GetVCPCapability VCP code success : " + vcp.Code.ToString() + ", value : " + objGetVCP.value.ToString());
                                    if (code == 0x66)
                                    {
                                        writelog($"[SetVCPSequence] Print GetAllExistAlsConfig Set 0x66, value {impVCPSequence.ALSConfig.ToString()} ... ");
                                        List<ALSConfig> existAlsConfig3 = _DisplayManagerPlugin.GetAllExistAlsConfig().Result;
                                        if (SetVCPCapability(monitorInfo, 0x66, impVCPSequence.ALSConfig).Result)
                                        {
                                            writelog("[SetVCPSequence] Print GetAllExistAlsConfig after Set 0x66, value" + impVCPSequence.ALSConfig.ToString());
                                            List<ALSConfig> existAlsConfig = _DisplayManagerPlugin.GetAllExistAlsConfig().Result;
                                            if (_DisplayManagerPlugin.UpdateImportAlsValueAsync(monitorInfo, impVCPSequence.ALSConfig).Result)
                                                writelog("[SetVCPSequence] UpdateImportAlsValueAsync success ...");
                                            else
                                                writelog("[SetVCPSequence] UpdateImportAlsValueAsync fail ...");
                                        }
                                        else
                                        {
                                            writelog("[SetVCPSequence] Set ALS(0x66) fail : Value = " + impVCPSequence.ALSConfig.ToString());
                                        }
                                    }
                                    else
                                    {
                                        if (((impVCPSequence.ALSConfig & (1u << 5)) != 0) && (code == 102 || code == 103))// if primary on, need to by pass 0x67 0x68
                                        {
                                            writelog("[SetVCPSequence] Set VCP code by pass : " + impVCPSequence.ALSConfig.ToString() + ", Value : " + code.ToString());
                                        }
                                        else
                                        {
                                            if (SetVCPCapability(monitorInfo, (byte)code, (uint)vcp.Value[0]).Result)
                                            {
                                                writelog("[SetVCPSequence] Set VCP code success : " + code.ToString() + ", Value : " + vcp.Value[0].ToString());
                                            }
                                            else
                                            {
                                                writelog("[SetVCPSequence] Set VCP code fail : " + code.ToString() + ", Value : " + vcp.Value[0].ToString());
                                            }
                                        }
                                    }
                                }
                            }
                            else
                            {
                                writelog($"[SetVCPSequence] Code:{code} cannot find in vcps");
                            }
                        }
                    }
                    else
                    {
                        writelog("[SetVCPSequence] vcps count = 0");
                    }
                }
                else
                {
                    writelog("[SetVCPSequence] ImpExpSettings is null");
                }
                writelog("[SetVCPSequence] SetVCPSequence ... out ");
            }
            catch (Exception ex)
            {
                writelog($"[SetVCPSequence] there is an exception-- ({ex.Message})");
            }
        }

        private void InitMonitorSettings(List<MonitorInfo> AllInfoMonitors, CancellationToken cancellationToken)
        {
            try
            {
                List<DDPMMonitorSettings> monitorSettingsList = new List<DDPMMonitorSettings>();

                if (AllInfoMonitors != null && _SettingsPlugin != null)
                {
                    writelog("[InitMonitorSettings] AllInfoMonitors count = " + AllInfoMonitors.Count.ToString());

                    var AllInfoMonitorsClone = AllInfoMonitors.ToList();

                    foreach (MonitorInfo m in AllInfoMonitors.ToList())
                    {
                        if (cancellationToken.IsCancellationRequested)
                            break;

                        monitorSettingsList = _SettingsPlugin.InitDDPMMonitorConfigFile(m.modelName, out isInitMonitorSettings).Result;

                        cancellationToken.ThrowIfCancellationRequested();  //----Extra Check Is Cancellation?

                        if (isInitMonitorSettings)
                        {
                            if (monitorSettingsList == null)
                            {
                                monitorSettingsList = new List<DDPMMonitorSettings>();
                            }

                            Trace.WriteLine("ServiceTag:" + m.edid.ServiceTag);

                            if (monitorSettingsList.Count == 0 || !monitorSettingsList.Exists(x => x.ServiceTag == m.edid.ServiceTag))
                            {
                                DDPMMonitorSettings settings = new DDPMMonitorSettings();
                                settings.Model = m.modelName;
                                settings.ServiceTag = m.edid.ServiceTag;
                                settings.VCPs = GetAllVCPcode(m);
                                settings.DisplayPropertiesInfo = new DisplayCurrentPropertiesInfo();
                                settings.EA = new EAMonitorSettings();
                                settings.easyArrangementDDPM = new EasyArrangementDDPM();
                                settings.ImpExpSettings = new ImpExpSettings();
                                settings.hotkeyData = new List<HotkeyData>();
                                settings.ALSConfig = 0;

                                // scheduleInfo PIMS-302114
                                {
                                    if (m.modelName.Equals("UP2720Q", StringComparison.OrdinalIgnoreCase))
                                    {
                                        settings.scheduleInfo = new scheduleInfo()
                                        {
                                            model = m.modelName,
                                            serviceTag = m.edid.ServiceTag,
                                            Brightness1 = 150,
                                            Brightness2 = 150,
                                        };
                                    }
                                    else if (m.modelName.Equals("UP2720QA", StringComparison.OrdinalIgnoreCase))
                                    {
                                        settings.scheduleInfo = new scheduleInfo()
                                        {
                                            model = m.modelName,
                                            serviceTag = m.edid.ServiceTag,
                                            Brightness1 = 150,
                                            Brightness2 = 150,
                                        };
                                    }
                                    else if (m.modelName.Equals("UP3221Q", StringComparison.OrdinalIgnoreCase))
                                    {
                                        settings.scheduleInfo = new scheduleInfo()
                                        {
                                            model = m.modelName,
                                            serviceTag = m.edid.ServiceTag,
                                            Brightness1 = 230,
                                            Brightness2 = 230,
                                        };
                                    }
                                    else
                                    {
                                        settings.scheduleInfo = new scheduleInfo()
                                        {
                                            model = m.modelName,
                                            serviceTag = m.edid.ServiceTag
                                        };
                                    }
                                }

                                monitorSettingsList.Add(settings);
                                bool b = _SettingsPlugin.WriteMonitorSettings(m.modelName, monitorSettingsList).Result;

                                Task.Run(() =>
                                {
                                    if (_ColorProfileHelper == null)
                                        writelog("[InitMonitorSettings] null _ColorProfileHelper");
                                    _ColorProfileHelper?.PreDownloadICC(m);//
                                }, cancellationToken);
                            }
                        }
                    }
                }
                else
                {
                    writelog("[InitMonitorSettings] AllInfoMonitors or _SettingsPlugin is null");
                }
            }
            catch (TaskCanceledException)
            {
                writelog("[InitMonitorSettings] _cancellationTokenSource trigger cancel cancellation happened ...");
            }
            catch (OperationCanceledException)
            {
                writelog("[InitMonitorSettings] _cancellationTokenSource trigger cancel cancellation happened ...");
            }
            catch (Exception ex)
            {
                writelog($"[InitMonitorSettings] _cancellationTokenSource ...there is an exception-- ({ex.Message})");
            }
        }

        //01/03 Jason add Hotkey to same model
        private void UpdateHotkeyInfo(CancellationToken cancellationToken)
        {
            List<DDPMMonitorSettings> monitorSettingsList = new List<DDPMMonitorSettings>();
            if (_AllInfoMonitors != null && _SettingsPlugin != null)
            {
                foreach (MonitorInfo m in _AllInfoMonitors.ToList())
                {
                    if (cancellationToken.IsCancellationRequested)
                        break;

                    monitorSettingsList = _SettingsPlugin.ReloadMonitorSettings(m.modelName).Result;
                    if (monitorSettingsList != null && monitorSettingsList.Count > 1)
                    {
                        List<HotkeyData> hotkeyDatas = new List<HotkeyData>();

                        foreach (DDPMMonitorSettings monitorSettings in monitorSettingsList)
                        {
                            if (cancellationToken.IsCancellationRequested)
                                break;

                            if (monitorSettings != null &&
                                monitorSettings.hotkeyData.Count > 0)
                            {
                                writelog("[UpdateHotkeyInfo] monitor : " + monitorSettings.Model);
                                foreach (HotkeyData hotkey in monitorSettings.hotkeyData)
                                {
                                    if (cancellationToken.IsCancellationRequested)
                                        break;

                                    writelog("[UpdateHotkeyInfo] hotkeyType : " + hotkey.hotkeyType);
                                    if ((hotkey.hotkeyType != HotkeyType.FavoriteInputSource &&
                                        hotkey.hotkeyType != HotkeyType.SwitchInputSource) &&
                                        !hotkeyDatas.Exists(x => x.hotkeyType == hotkey.hotkeyType))
                                    {
                                        writelog("[UpdateHotkeyInfo] add hotkeyType to hotkeyDatas.");
                                        hotkeyDatas.Add(hotkey);
                                    }
                                }
                            }
                        }

                        foreach (DDPMMonitorSettings monitorSettings in monitorSettingsList)
                        {
                            if (cancellationToken.IsCancellationRequested)
                                break;

                            if (monitorSettings != null)
                            {
                                writelog("[UpdateHotkeyInfo] monitor : " + monitorSettings.Model);
                                foreach (HotkeyData hotkey in hotkeyDatas)
                                {
                                    if (cancellationToken.IsCancellationRequested)
                                        break;

                                    if (!monitorSettings.hotkeyData.Exists(x => x.hotkeyType == hotkey.hotkeyType))
                                    {
                                        writelog("[UpdateHotkeyInfo] add hotkeyType to monitorSettings.");
                                        monitorSettings.hotkeyData.Add(hotkey);
                                    }
                                }
                            }
                        }

                        bool b = _SettingsPlugin.WriteMonitorSettings(m.modelName, monitorSettingsList).Result;
                    }
                }
            }
        }

