                                              (app => new EAAppInfoDDPM(app.Name, app.Path, app.IsUWP, app.AppUserModelID, app.Param)));

                        // 將更新後的 currentProfile 寫入
                        result = WriteUserEAProfileDDPM(null, eaProfileDDPM).Result;
                    }
                    if (result)
                        writelog($"@ DDMtoDDPM_EzMemory: UserSettings PASS");
                    else
                        writelog($"@ DDMtoDDPM_EzMemory: UserSettings Fail");
                }
                */

                //DDMMonitorSettings
                if (dDMMonitorSettings != null && dDMMonitorSettings.EasyArrangement != null)
                {
                    MonitorInfo moinfo = new MonitorInfo();
                    EDID edid = new EDID();
                    moinfo.edid = edid;
                    moinfo.modelName = dDMMonitorSettings.Model;
                    moinfo.edid.ModelName = dDMMonitorSettings.Model;
                    moinfo.edid.ServiceTag = dDMMonitorSettings.ServiceTag;

                    EasyArrangementDDPM easyArrangementDDPM = new EasyArrangementDDPM();
                    easyArrangementDDPM.Desktops = new List<DesktopDDPM>();

                    // 新增 DesktopDDPM 物件
                    easyArrangementDDPM.Desktops.Add(new DesktopDDPM(dDMMonitorSettings.EasyArrangement.Desktops[0].ID, dDMMonitorSettings.EasyArrangement.Desktops[0].ActiveLayout));

                    // 設定 DesktopDDPM 的屬性
                    easyArrangementDDPM.Desktops[0].ID = dDMMonitorSettings.EasyArrangement.Desktops[0].ID;
                    easyArrangementDDPM.Desktops[0].Index = dDMMonitorSettings.EasyArrangement.Desktops[0].Index;
                    easyArrangementDDPM.Desktops[0].ActiveLayout = dDMMonitorSettings.EasyArrangement.Desktops[0].ActiveLayout;

                    List<int> layoutMRU = new List<int>();
                    layoutMRU = dDMMonitorSettings.EasyArrangement.Desktops[0].LayoutMRU;
                    easyArrangementDDPM.Desktops[0].LayoutMRU = layoutMRU;

                    List<int> profileMRU = new List<int>();
                    profileMRU = dDMMonitorSettings.EasyArrangement.Desktops[0].ProfileMRU;
                    easyArrangementDDPM.Desktops[0].ProfileMRU = profileMRU;

                    // Profiles
                    easyArrangementDDPM.Desktops[0].Profiles = new List<EzProfileDDPM>();
                    foreach (var profile in dDMMonitorSettings.EasyArrangement.Desktops[0].Profiles)
                    {
                        var newProfile = new EzProfileDDPM(
                            profile.ID,
                            profile.Name,
                            profile.Layout,
                            profile.Auto,
                            profile.AutoStartTime ?? 0,
                            profile.StartUpLaunch,
                            new List<EAAppInfoDDPM>()
                        );

                        // AppInfos
                        foreach (var app in profile.AppInfos)
                        {
                            var newAppInfo = new EAAppInfoDDPM(
                                app.Name,
                                app.Path,
                                app.IsUWP,
                                app.AppUserModelID,
                                app.Param
                            );
                            newProfile.AppInfos.Add(newAppInfo);
                        }

                        easyArrangementDDPM.Desktops[0].Profiles.Add(newProfile);
                    }

                    // ProfileSettings
                    easyArrangementDDPM.Desktops[0].ProfileSettings = new List<EzProfileSettingDDPM>();
                    foreach (var setting in dDMMonitorSettings.EasyArrangement.Desktops[0].ProfileSettings)
                    {
                        var newSetting = new EzProfileSettingDDPM(
                            setting.ID,
                            setting.Auto,
                            setting.AutoStartTime ?? 0,
                            setting.StartUpLaunch
                        );

                        easyArrangementDDPM.Desktops[0].ProfileSettings.Add(newSetting);
                    }
                    result = WriteMonitorEasyArrangement(moinfo, easyArrangementDDPM).Result;
                }
                if (result)
                    writelog($"@ DDMtoDDPM_EzMemory: MonitorSettings PASS");
                else
                    writelog($"@ DDMtoDDPM_EzMemory: MonitorSettings Fail");
            }
            catch (Exception ex)
            {
                writelog($"@ DDMtoDDPM_EzMemory: {ex.Message}");
            }
            return Task.FromResult(result);
        }

        private void DDMMigration()
        {
            if (_SettingsPlugin != null)
            {
                string migration = string.Empty;
                if (_SettingsPlugin.isDDMMigration(out migration).Result)
                {
                    DDMUserSettings ddmUserSettings = new DDMUserSettings();
                    string migrationPath = migration + "\\" + "UserFoler";
                    DirectoryInfo di = new DirectoryInfo(migrationPath);
                    if (_SettingsPlugin.ReadDDMUserSettings(migrationPath + "\\UserSettings", ref ddmUserSettings).Result)
                    {
                        //Hotkey
                        //DDMtoDDPM_Hotkey(ddmUserSettings);
                        //HotkeySettings hotkeySettings = new HotkeySettings();
                        hotkeySettings.ServiceTag = "DDPM";
                        hotkeySettings.SerialNumber = "DDPM";
                        hotkeySettings.ModelName = "DDPM";
                        List<DDMMonitorSettings> _dDMMonitorCache = new List<DDMMonitorSettings>();
                        Dictionary<string, bool> modelImportFlags = new Dictionary<string, bool>();

                        // Override the ApplicationSettingsImportYesOrNo for each model setup
                        FileInfo[] dDMFiles = di.GetFiles("*_*");
                        foreach (var file in dDMFiles)
                        {
                            WriteLog($"[DDMMigration] Start processing file: {file.Name} ...");
                            DDMMonitorSettings DDMmonitorsettings = new DDMMonitorSettings();
                            string path = migrationPath + "\\" + file.Name;
                            if (_SettingsPlugin.ReadDDMMonitorSettings(path, ref DDMmonitorsettings).Result)
                            {
                                //cache DDM monitor data for model update
                                _dDMMonitorCache.Add(DDMmonitorsettings);
                                if (string.IsNullOrEmpty(DDMmonitorsettings.ServiceTag)
                                    && !modelImportFlags.ContainsKey(file.Name.Trim('_')))
                                {
                                    modelImportFlags.Add(file.Name.Trim('_'), DDMmonitorsettings.Display.ApplicationSettingsImportYesOrNo);
                                }
                            }
                            else
                            {
                                writelog($"[DDMMigration] read DDM MonitorSettings file fail: {path}");
                            }
                        }

                        // Loop through DDM monitor files
                        foreach (var dDMMonitorSetting in _dDMMonitorCache)
                        {
                            if (dDMMonitorSetting.ServiceTag != string.Empty)
                            {
                                //add settings file in DDPM
                                bool binit = false;
                                List<DDPMMonitorSettings> ddpmMonitorSettings = new List<DDPMMonitorSettings>();
                                ddpmMonitorSettings = _SettingsPlugin.ReloadMonitorSettings(dDMMonitorSetting.Model).Result;
                                if (ddpmMonitorSettings == null)
                                {
                                    ddpmMonitorSettings = _SettingsPlugin.InitDDPMMonitorConfigFile(dDMMonitorSetting.Model, out binit).Result;
                                }
                                else
                                {
                                    if (ddpmMonitorSettings.Count == 0)
                                    {
                                        ddpmMonitorSettings = _SettingsPlugin.InitDDPMMonitorConfigFile(dDMMonitorSetting.Model, out binit).Result;
                                    }
                                    else
                                    {
                                        binit = true;
                                    }
                                }
                                if (binit)
                                {
                                    if (ddpmMonitorSettings == null)
                                    {
                                        ddpmMonitorSettings = new List<DDPMMonitorSettings>();
                                        DDPMMonitorSettings settings = new DDPMMonitorSettings();
                                        settings.Model = dDMMonitorSetting.Model;
                                        settings.ServiceTag = dDMMonitorSetting.ServiceTag;
                                        ddpmMonitorSettings.Add(settings);
                                        bool b = _SettingsPlugin.WriteMonitorSettings(dDMMonitorSetting.Model, ddpmMonitorSettings).Result;
                                    }
                                    else
                                    {
                                        if (!ddpmMonitorSettings.Exists(x => (x.ServiceTag == dDMMonitorSetting.ServiceTag)))
                                        {
                                            DDPMMonitorSettings settings = new DDPMMonitorSettings();
                                            settings.Model = dDMMonitorSetting.Model;
                                            settings.ServiceTag = dDMMonitorSetting.ServiceTag;
                                            ddpmMonitorSettings.Add(settings);
                                            bool b = _SettingsPlugin.WriteMonitorSettings(dDMMonitorSetting.Model, ddpmMonitorSettings).Result;
                                        }
                                    }

                                    bool? isSameModel = null;
                                    if (modelImportFlags.ContainsKey(dDMMonitorSetting.Model))
                                        isSameModel = modelImportFlags[dDMMonitorSetting.Model];
                                    //DDM settings -> DDPM settings
                                    ImportDDMMonitorSettings(dDMMonitorSetting, ddmUserSettings, isSameModel);
                                }
                                else
                                {
                                    writelog("[DDMMigration] InitDDPMMonitorConfigFile fail");
                                }
                            }
                        }

                        if (CopyFile(migrationPath, migration + "\\" + "CopyMigrationFile"))
                        {
                            try
                            {
                                Directory.Delete(migrationPath, true);
                                writelog("[DDMMigration] delete temp folder success");
                            }
                            catch (Exception ex)
                            {
                                writelog($"[DDMMigration] delete temp folder exception: {migrationPath}");
                                writelog($"[DDMMigration] delete temp folder exception: {ex.Message}");
                            }
                        }
                    }
                    else
                    {
                        writelog($"[DDMMigration] read DDM UserSettings file fail: {migrationPath + "\\UserSettings"}");
                    }
                }
                else
                {
                    writelog("[DDMMigration] not find Migration folder.");
                }
            }
        }

        private void ImportDDMMonitorSettings(DDMMonitorSettings DDMmonitorsettings, DDMUserSettings DDMusersettings, bool? isSameModel = null)
        {
            //Input
            DDMtoDDPM_Input(DDMmonitorsettings);
            //Color
            if (_ColorPresetPlugin != null)
            {
                _ColorPresetPlugin.Migration(DDMmonitorsettings.ColorPreset, DDMmonitorsettings.Model, DDMmonitorsettings.ServiceTag, _SettingsPlugin);
            }
            //KVM
            DDMtoDDPM_KVM(DDMmonitorsettings);
            //EA
            DDMtoDDPM_EzArrange(DDMmonitorsettings, DDMusersettings);
            //EM
            //Robert_Lin 2025-4-23, move the migration code of EasyMemory into DDMtoDDPM_EzArrange()
            //        DDMtoDDPM_EzMemory(DDMmonitorsettings, DDMusersettings);
            //Schedule
            bool bSchedule = MigrateScheduleMonitorSettings(DDMmonitorsettings.Model, DDMmonitorsettings.ServiceTag, DDMmonitorsettings.BriConSchedule).Result;
            //Hotkey
            DDMtoDDPM_Hotkey(DDMusersettings, DDMmonitorsettings);
            //PowerNap
            DDMtoDDPM_PowerNap(DDMmonitorsettings);
            //Consent Page
            DDMtoDDPM_ConsentPage(DDMusersettings);

            if (isSameModel != null)
                DDMtoDDPM_IsSameModel(DDMmonitorsettings, (bool)isSameModel);
        }

        private void DDMtoDDPM_KVM(DDMMonitorSettings ddmMonitorSettings)
        {
            try
            {
                if (ddmMonitorSettings != null)
                {
                    string model = ddmMonitorSettings.Model;
                    string serviceTag = ddmMonitorSettings.ServiceTag;
                    bool isUSBOn = false;
                    bool isNetOn = false;
                    if (ddmMonitorSettings.KVM.USB.WizardRuned && ddmMonitorSettings.KVM.Network.WizardRuned)
                    {
                        if (ddmMonitorSettings.KVM.LastUsed == (int)KVMType.USB)
                        {
                            isUSBOn = true;
                        }
                        else
                        {
                            isNetOn = true;
                        }
                    }
                    else if (ddmMonitorSettings.KVM.USB.WizardRuned && !ddmMonitorSettings.KVM.Network.WizardRuned)
                    {
                        isUSBOn = true;
                    }
                    else if (!ddmMonitorSettings.KVM.USB.WizardRuned && ddmMonitorSettings.KVM.Network.WizardRuned)
                    {
                        isNetOn = true;
                    }
                    if (_SettingsPlugin != null)
                    {
                        List<DDPMMonitorSettings> ddpmMonitorSettings = _SettingsPlugin.ReloadMonitorSettings(model).Result;
                        if (ddpmMonitorSettings != null)
                        {
                            int index = ddpmMonitorSettings.FindIndex(x => x.ServiceTag == serviceTag);
                            if (index != -1)
                            {
                                ddpmMonitorSettings[index].KVM.isOnUSBKVM = isUSBOn;
                                ddpmMonitorSettings[index].KVM.isOnNKVM = isNetOn;
                            }
                            else
                            {
                                DDPMMonitorSettings monitorSettings = new DDPMMonitorSettings();
                                monitorSettings.Model = model;
                                monitorSettings.ServiceTag = serviceTag;
                                monitorSettings.KVM.isOnUSBKVM = isUSBOn;
                                monitorSettings.KVM.isOnNKVM = isNetOn;
                                ddpmMonitorSettings.Add(monitorSettings);
                            }

                            bool b = _SettingsPlugin.WriteMonitorSettings(model, ddpmMonitorSettings).Result;
                        }
                        else
                        {
                            writelog("[DDMtoDDPM_KVM]ddpmMonitorSettings is null!");
                        }
                    }
                    else
                    {
                        writelog("[DDMtoDDPM_KVM]_SettingsPlugin is null!");
                    }
                }
                else
                {
                    writelog("[DDMtoDDPM_KVM]ddmMonitorSettings is null!");
                }
            }
            catch (Exception ex)
            {
                writelog($"DDMtoDDPM_KVM Exception {ex.Message.ToString()}");
            }
        }

        private void DDMtoDDPM_Hotkey(DDMUserSettings ddmUserSettings, DDMMonitorSettings ddmMonitorSettings)
        {
            try
            {
                if (_SettingsPlugin != null)
                {
                    List<HotkeySettings> hotkeySettingList = _SettingsPlugin.ReadHotkeySettings().Result;
                    if (ddmUserSettings != null)
                    {
                        foreach (var Hotkey in ddmUserSettings.Hotkeys)
                        {
                            if (Hotkey.Keys != null &&
                                Hotkey.Keys.Count != 0)
                            {
                                //DDMtoDDPM dDMtodDPM = new DDMtoDDPM();
                                if (dDMtodDPM.HotkeyMap.TryGetValue(Hotkey.Function, out HotkeyType hotkeyType))
                                {
                                    writelog($"[DDMtoDDPM_Hotkey] Fun is {Hotkey.Function}");
                                    //HotkeySettings hotkeySettings = new HotkeySettings();
                                    HotkeyInfo hotkeyInfo = new HotkeyInfo();
                                    //hotkeySettings.ServiceTag = "DDPM";
                                    //hotkeySettings.SerialNumber = "DDPM";
                                    //hotkeySettings.ModelName = "DDPM";
                                    //hotkeyInfo = new HotkeyInfo();
                                    hotkeyInfo.Job = hotkeyType;
                                    hotkeyInfo.Hotkey = new List<VirtualKey>();
                                    if (hotkeyInfo.Hotkey != null)
                                    {
                                        foreach (int key in Hotkey.Keys)
                                        {
                                            writelog($"[DDMtoDDPM_Hotkey] Key is {key}");
                                            if (key == -1)
                                            {
                                                continue;
                                            }
                                            else if (key == 262144)
                                            {
                                                hotkeyInfo.Hotkey.Add(VirtualKey.Menu);
                                            }
                                            else if (key == 131072)
                                            {
                                                hotkeyInfo.Hotkey.Add(VirtualKey.Control);
                                            }
                                            else if (key == 65536)
                                            {
                                                hotkeyInfo.Hotkey.Add(VirtualKey.Shift);
                                            }
                                            else
                                            {
                                                VirtualKey Vkey = (VirtualKey)key;
                                                hotkeyInfo.Hotkey.Add(Vkey);
                                            }
                                        }
                                        if (hotkeyInfo.Hotkey.Count != 0 && !hotkeySettings.HotkeyInfo.Exists(x => x.Job == hotkeyInfo.Job))
                                        {
                                            hotkeySettings.HotkeyInfo.Add(hotkeyInfo);
                                        }
                                    }
                                }
                            }
                        }
                        hotkeySettingList.Clear();
                        hotkeySettingList.Add(hotkeySettings);
                        bool b = _SettingsPlugin.WriteHotkeySettings(hotkeySettingList).Result;
                    }
                    if (ddmMonitorSettings != null)
                    {
                        List<DDPMMonitorSettings> monitorSettingList = new List<DDPMMonitorSettings>();
                        monitorSettingList = _SettingsPlugin.ReloadMonitorSettings(ddmMonitorSettings.Model).Result;
                        if (monitorSettingList != null)
                        {
                            DDPMMonitorSettings monitorSettings = monitorSettingList.Find(x => (x.ServiceTag == ddmMonitorSettings.ServiceTag));
                            if (monitorSettings != null)
                            {
                                List<HotkeyData> hotkeyDataList = new List<HotkeyData>();
                                hotkeyDataList = monitorSettings.hotkeyData;
                                if (hotkeyDataList != null)
                                {
                                    if (ddmMonitorSettings.Input.FavoriteHotkeyInput != 0)
                                    {
                                        HotkeyData hotkeyData = new HotkeyData();
                                        hotkeyData.hotkeyType = HotkeyType.FavoriteInputSource;
                                        List<InputSourceObj> inputSourceObjs = new List<InputSourceObj>();
                                        InputSourceObj inputSourceObj = new InputSourceObj();
                                        inputSourceObj.Name = string.Empty;
                                        inputSourceObj.Code = (UInt16)ddmMonitorSettings.Input.FavoriteHotkeyInput;
                                        inputSourceObjs.Add(inputSourceObj);
                                        hotkeyData.inputSource = inputSourceObjs;
                                        monitorSettings.hotkeyData.Add(hotkeyData);
                                    }
                                    if (ddmMonitorSettings.Input.Toogle2InputHotkeysInfo.Count != 0)
                                    {
                                        HotkeyData hotkeyData = new HotkeyData();
                                        hotkeyData.hotkeyType = HotkeyType.SwitchInputSource;
                                        List<InputSourceObj> inputSourceObjs = new List<InputSourceObj>();
                                        foreach (int input in ddmMonitorSettings.Input.Toogle2InputHotkeysInfo)
                                        {
                                            InputSourceObj inputSourceObj = new InputSourceObj();
                                            inputSourceObj.Name = string.Empty;
                                            inputSourceObj.Code = (UInt16)input;
                                            inputSourceObjs.Add(inputSourceObj);
                                        }
                                        hotkeyData.inputSource = inputSourceObjs;
                                        monitorSettings.hotkeyData.Add(hotkeyData);
                                    }
                                    bool bh = _SettingsPlugin.WriteMonitorSettings(ddmMonitorSettings.Model, monitorSettingList).Result;
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                writelog($"[DDMtoDDPM_Hotkey] error is {ex.Message}");
            }
        }

        private DisplayCurrentPropertiesInfo DDMtoDDPM_DisplayProperties(DDMMonitorSettings DDMmonitorsettings)
        {
            DisplayCurrentPropertiesInfo ret = null;
            try
            {
                ret = new DisplayCurrentPropertiesInfo();
                ret.CurrentProperties.Resolutions_Width = DDMmonitorsettings.Display.devmode.dmPelsWidth;
                ret.CurrentProperties.Resolutions_High = DDMmonitorsettings.Display.devmode.dmPelsHeight;
                ret.CurrentProperties.Frequency = DDMmonitorsettings.Display.devmode.dmDisplayFrequency;
                ret.CurrentOrientation = (DisplayOrientation)(DDMmonitorsettings.Display.orientation - 1);
                ret.isHDREnable = DDMmonitorsettings.Display.SmartHDR;
            }
            catch
            {
                ret = null;
            }
            return ret;
        }

        private bool Import_DisplayProperties(MonitorInfo monitorInfo, DisplayCurrentPropertiesInfo displayCurrentPropertiesInfo)
        {
            bool ret = false;
            try
            {
                //MonitorInfo monitorInfo = new MonitorInfo();
                ret = SetDisplayPropertiest(monitorInfo, displayCurrentPropertiesInfo.CurrentProperties, displayCurrentPropertiesInfo.CurrentOrientation).Result;
                ret = SetHDRStatus(monitorInfo, displayCurrentPropertiesInfo.isHDREnable).Result && ret;
                if (displayCurrentPropertiesInfo.USBCPrioritizationType != USBCPrioritizationType.Unknow)
                {
                    ret = SetUSBCPrioritizationType(monitorInfo, displayCurrentPropertiesInfo.USBCPrioritizationType).Result && ret;
                }
                ret = true;
            }
            catch
            {
                ret = false;
            }
            return ret;
        }

        private DisplayCurrentPropertiesInfo Export_DisplayProperties(MonitorInfo monitorInfo)
        {
            DisplayCurrentPropertiesInfo ret = null;
            try
            {
                if (_DisplayManagerPlugin != null)
                {
                    ret = _DisplayManagerPlugin.GetCurrentDisplayProperties(monitorInfo).Result;
                }
            }
            catch
            {
                ret = null;
            }
            return ret;
        }

        private bool CopyFile(string copyPath, string savePath)
        {
            writelog($"{nameof(CopyFile)} start");

            using (Method method = new Method(Log))//Bruce 1213 Move the method to the common code)
            {
                if (_DisplayManagerPlugin != null)
                {
                    // 確保資料夾存在
                    if (!Directory.Exists(savePath))
                    {
                        Directory.CreateDirectory(savePath);
                    }

                    if (method.DirectoryContainsFiles(copyPath))//Bruce 1213 Move the method to the common code
                    {
                        // 取得資料夾名稱
                        string folderName = method.GetFolderName(copyPath);//Bruce 1213 Move the method to the common code
                                                                           // 複製指定的 log 文件到選擇的資料夾
                        method.CopyLogFolder(copyPath, savePath);//Bruce 1213 Move the method to the common code
                        writelog($"{nameof(CopyFile)} end");
                        return true;
                    }
                }

                writelog($"{nameof(CopyFile)} end");
                return false;
            }
        }

        //Robert_Lin, 2025-4-20 Rewrite this method
        //Robert_Lin, 2024-10-11, added. Called for each {Model}_{ServiceTag}
        private void DDMtoDDPM_EzArrange(DDMMonitorSettings ddmMonitorSettings, DDMUserSettings ddmUserSettings)
        {
            if (_SettingsPlugin == null)
            {
                writelog($"@ DDMtoDDPM_EzArrange() do nothing:  _SettingsPlugin is null.");
                return;
            }

            //This cutsom list will be used to query settings when migrating monitor settings
            List<SplitJson> ddpmCustomList = new List<SplitJson>();

            //Migration UserSettings
            //
            if (ddmUserSettings != null)
            {
                //Phase I Convert DDMUserSettings.CustLayouts to ddpmCustomList
                if (ddmUserSettings.CustLayouts != null)
                {
                    #region Migration_EAM Phase I - Custom List
                    writelog($"@ DDMtoDDPM_EzArrange() - Phase I - migrate DDM User Settings.CustLayouts. Count={ddmUserSettings.CustLayouts.Count}");

                    int idxCustLayout = 0;
                    foreach (CustLayout custLayout in ddmUserSettings.CustLayouts)
                    {
                        SplitJson spJson = new SplitJson();
                        spJson.CellCount = 0;
                        spJson.SplitKey = 'B';

                        List<double> settings = new List<double>();
                        //Format: settings[0] : BorderCount
                        settings.Add((double)custLayout.Rects.Count);
                        //settings[1] : screenScale
                        settings.Add((double)1.000);
                        //settings[2] : screenWidth
                        settings.Add((double)1.000);
                        //settings[3] : screenHeight
                        settings.Add((double)1.000);

                        //Settings[4 ~] : Rects
                        int idxRect = 0;
                        StringBuilder sbRects = new StringBuilder();
                        sbRects.Append("Rects: { ");
                        foreach (EARect eARect in custLayout.Rects)
                        {
                            if (idxRect > 0)
                                sbRects.Append(", ");

                            string rectText = $"({eARect.x}, {eARect.y}, {eARect.w}, {eARect.h})";
                            sbRects.Append(rectText);

                            //settings[4 + idxRect + 0] : left
                            settings.Add(eARect.x);
                            //settings[4 + idxRect + 1] : top
                            settings.Add(eARect.y);
                            //settings[4 + idxRect + 2] : width
                            settings.Add(eARect.w);
                            //settings[4 + idxRect + 3] : height
                            settings.Add(eARect.h);
                            idxRect++;
                        }

                        sbRects.Append(" }");

                        spJson.Settings = settings;
                        spJson.CustomName = custLayout.Name;
                        spJson.CustomId = custLayout.ID;
                        spJson.EAID = custLayout.ID;

                        ddpmCustomList.Add(spJson);

                        writelog($"  * CustLayout[{idxCustLayout}]: ID=[{custLayout.ID}], Name=[{custLayout.Name}], Overlap=[{custLayout.Overlap}], Rects={sbRects.ToString()} => {spJson.ToString()}");
                        idxCustLayout++;
                    } //foreach (CustLayout custLayout in ddmUserSettings.CustLayouts)

                    bool saveCustomListOK = WriteEACustomList(ddpmCustomList.ToArray()).Result;
                    writelog($"  * WriteEACustomList() return {saveCustomListOK}");
                    #endregion Migration_EAM Phase I - Custom List
                }// if (ddmUserSettings.CustLayouts != null)

                //Phase II Convert EasyArrange Per-user settings (EzSettings)
                //
                #region Migration_EAM Phase II - EzSettings
                writelog($"@ DDMtoDDPM_EzArrange() - Phase II - migrate DDM User Settings: EzSettings");

                bool saveOK = WriteEzSettings_IsWidthoutGap(ddmUserSettings.EAWithoutGap).Result;
                writelog($"  * EAWithoutGap -> IsWidthoutGap = {ddmUserSettings.EAWithoutGap} ... Result={saveOK}");

                saveOK = WriteEzSettings_IsOnlyAllowWhenShiftKeyPressed(ddmUserSettings.EAWithShiftKey).Result;
                writelog($"  * EAWithShiftKey -> IsOnlyAllowWhenShiftKeyPressed = {ddmUserSettings.EAWithShiftKey} ... Result={saveOK}");

                saveOK = WriteEzSettings_IsSpanAcrossMultiMonitors(ddmUserSettings.EASpan).Result;
                writelog($"  * EASpan -> IsSpanAcrossMultiMonitors = {ddmUserSettings.EASpan} ... Result={saveOK}");

                saveOK = WriteEzSettings_IsAwsEnabled(ddmUserSettings.SnapEnable).Result;
                writelog($"  * SnapEnable -> IsAwsEnabled = {ddmUserSettings.SnapEnable} ... Result={saveOK}");
                #endregion Migration_EAM Phase II - EzSettings

                //Phase III - Migrate EasyMemory UserSettings
                #region Migration_EAM Phase III - EasyMemory UserSettings
                Migrate_EzMemory_UserSettings(ddmUserSettings);
                #endregion Migration_EAM Phase III - EasyMemory UserSettings
            } //if (ddmUserSettings != null)
            else
            {
                writelog($"@ DDMtoDDPM_EzArrange() - Phase I~III - ddmUserSettings is null.");
            }

            if (ddmMonitorSettings == null)
            {
                writelog($"@ DDMtoDDPM_EzArrange() - Phase IV - ddmMonitorSettings is null.");
                return;
            }
            if (ddmMonitorSettings.EasyArrangement == null)
            {
                writelog($"@ DDMtoDDPM_EzArrange() - Phase IV - ddmMonitorSettings.EasyArrangement is null.");
                return;
            }

            //Phase 3 Migration MonitorSettings
            //
            writelog($"@ DDMtoDDPM_EzArrange() - Phase IV - Migrate monitor settings.");

            string model = ddmMonitorSettings.Model;
            string serviceTag = ddmMonitorSettings.ServiceTag;
            int desktopCount = ddmMonitorSettings.EasyArrangement.Desktops.Count;
            writelog($"  * MonitorModel=[{model}], ServiceTag=[{serviceTag}], DesktopCount=[{desktopCount}]");

            //We need the custom list for this phase, if it's empty, then load from DDPM UserSettinge
            if (ddpmCustomList.Count <= 0)
            {
                ddpmCustomList.AddRange(ReadEACustomList().Result);
            }

            //The Data to be writen to DDPM Per-Monitor-Model-ServiceTag record
            List<EAMonitorSettings> ea1List = new List<EAMonitorSettings>();
            List<DesktopDDPM> ddpmDesktops = new List<DesktopDDPM>();

            int idxDesktop = 0;
            //Enumerate for each Instace and convert Desktop to EAMonitorSettings, add to eaPerServiceTagSettings
            foreach (Desktop ddmDesktop in ddmMonitorSettings.EasyArrangement.Desktops)
            {
                //
                //Desktop {                                                     EAMonitorSettings {
                //  string ID;                                                      string Instace;
                //  int Index; //unused, always 0
                //  int ActiveLayout;                                               SplitJson SelectedSplit;
                //  List<int> LayoutMRU;                                            SplitJson[] RecentList;
                //  List<int> ProfileMRU; //unused, always empty
                //  List<Profile> Profiles; //unused, always empty                 
                //  List<ProfileSetting> ProfileSettings; //used by Easy Memory

                //Create a object to collecting the settings from ddmMonitorSetting.EasyArrangement.Desktops[i]
                EAMonitorSettings eaPerInstanceSetting = new EAMonitorSettings();

                //ID -> Instace, fill ID only when Desktops.Count >1
                eaPerInstanceSetting.Instance = ddmDesktop.ID;
                writelog($"  * Desktop[{idxDesktop}].ID=[{ddmDesktop.ID}] => EA1[{idxDesktop}].Instance=[{eaPerInstanceSetting.Instance}]");

                //ActiveLayout -> SelectedSplit
                //If the layout is custom layout (EAID >= 1000)
                if (ddmDesktop.ActiveLayout >= EAEMConstants.EAID_FirstCustom)
                {
                    //Find the CustomLayout by EAID
                    SplitJson? cusJson = ddpmCustomList.Find(x => x.EAID == ddmDesktop.ActiveLayout);
                    if (cusJson != null)
                    {
                        SplitJson spjSel = cusJson.Clone();
                        eaPerInstanceSetting.SelectedSplit = spjSel;
                        writelog($"  * Desktop[{idxDesktop}].ActiveLayout=[{ddmDesktop.ActiveLayout}] => EA1[{idxDesktop}].SelectedSplit:{eaPerInstanceSetting.SelectedSplit.ToString()}");
                    }
                    else
                    {
                        //Not found in ddmUserSettings.CustLayouts, will set SelectedLayout to "Empty" (Off)
                        eaPerInstanceSetting.SelectedSplit = new SplitJson()
                        {
                            CellCount = 0,
                            SplitKey = 'A',
                            CustomId = 0,
                            EAID = 0
                        };
                        writelog($"  * Desktop[{idxDesktop}].ActiveLayout=[{ddmDesktop.ActiveLayout}] => ERROR: not found in ddmUserSettings.CustLayouts");
                    }
                }
                else //Preset layout
                {
                    SplitJson? presetJson = SplitJson.CreatePresetLayoutFromEAID(ddmDesktop.ActiveLayout);
                    if (presetJson != null)
                    {
                        eaPerInstanceSetting.SelectedSplit = presetJson;
                        writelog($"  * Desktop[{idxDesktop}].ActiveLayou=[{ddmDesktop.ActiveLayout}] => EA1[{idxDesktop}].SelectedSplit:{presetJson.ToString()}");
                    }
                    else
                    {
                        writelog($"  * Desktop[{idxDesktop}].ActiveLayout=[{ddmDesktop.ActiveLayout}] => ERROR: Invalid EAID");
                    }
                }

                //LayoutMRU -> RecentList
                List<SplitJson> recentList = new List<SplitJson>();
                int idxMRU = 0;
                foreach (int eaidRecent in ddmDesktop.LayoutMRU)
                {
                    //If the layout is a custom layout (EAID >= 1000)
                    if (eaidRecent >= EAEMConstants.EAID_FirstCustom)
                    {
                        //Find the CustomLayout by EAID
                        SplitJson? cusJson = ddpmCustomList.Find(x => x.EAID == eaidRecent);
                        if (cusJson != null)
                        {
                            SplitJson spjRecent = cusJson.Clone();
                            recentList.Add(spjRecent);
                            writelog($"  * Desktop[{idxDesktop}].LayoutMRU[{idxMRU}]=[{eaidRecent}] => EA1[{idxDesktop}].RecentList[{idxMRU}]:{spjRecent.ToString()}");
                        }
                        else
                        {
                            writelog($"  * Desktop[{idxDesktop}].LayoutMRU[{idxMRU}]=[{eaidRecent}] => ERROR: not found in ddmUserSettings.CustLayouts");
                        }
                    }
                    else //Preset layouts
                    {
                        //Preset layout
                        SplitJson? presetJson = SplitJson.CreatePresetLayoutFromEAID(eaidRecent);
                        if (presetJson != null)
                        {
                            recentList.Add(presetJson);
                            writelog($"  * Desktop[{idxDesktop}].LayoutMRU[{idxMRU}]=[{eaidRecent}] => EA1[{idxDesktop}].RecentList[{idxMRU}]:{presetJson.ToString()}");
                        }
                        else
                        {
                            writelog($"  * Desktop[{idxDesktop}].LayoutMRU[{idxMRU}]=[{eaidRecent}] => ERROR: Invalid EAID");
                        }
                    }

                    idxMRU++;
                } //foreach (int eaidRecent in ddmDesktop.LayoutMRU)

                eaPerInstanceSetting.RecentList = recentList.ToArray();
                ea1List.Add(eaPerInstanceSetting);

                //Migrate EasyMemory portion
                //   Desktop {
                //      List<Desktop> Desktops
                //
                DesktopDDPM ddpmDesktop = new DesktopDDPM(ddmDesktop.ID, ddmDesktop.ActiveLayout);
                ddpmDesktop.LayoutMRU = new List<int>(ddmDesktop.LayoutMRU);

                // Profiles
                ddpmDesktop.Profiles = new List<EzProfileDDPM>();
                foreach (var profile in ddmDesktop.Profiles)
                {
                    //Robert_Lin 2025-4-24, for those profiles that using custom layouts will not be migrated.
                    //It's because of the limitation in Custom layouts in DDM.
                    //There is not provide enough information in DDM settings to tell DDPM that the custom layout
                    //is edited from which preset layout.
                    //So all the custom layout of DDM will be converted to Overlap layouts.
                    //In EasyMemory, the profiles are support overlap layouts.
                    //So when migrate a profile using custom layout will not be migrated.

                    //If the layout (EAID) is a custom layout (EAID >= 1000)
                    if (profile.Layout >= EAEMConstants.EAID_FirstCustom)
                        continue;

                    var newProfile = new EzProfileDDPM(
                        profile.ID,
                        profile.Name,
                        profile.Layout,
                        profile.Auto,
                        profile.AutoStartTime ?? 0,
                        profile.StartUpLaunch,
                        new List<EAAppInfoDDPM>()
                    );

                    // AppInfos
                    foreach (var app in profile.AppInfos)
                    {
                        var newAppInfo = new EAAppInfoDDPM(
                            app.Name,
                            app.Path,
                            app.IsUWP,
                            app.AppUserModelID,
                            app.Param
                        );
                        newProfile.AppInfos.Add(newAppInfo);
                    }

                    ddpmDesktop.Profiles.Add(newProfile);
                } //foreach (var profile in ddmDesktop.Profiles)

                // ProfileSettings
                ddpmDesktop.ProfileSettings = new List<EzProfileSettingDDPM>();
                foreach (var setting in ddmDesktop.ProfileSettings)
                {
                    var newSetting = new EzProfileSettingDDPM(
                        setting.ID,
                        setting.Auto,
                        setting.AutoStartTime ?? 0,
                        setting.StartUpLaunch
                    );

                    //Robert_Lin, fix the AutoStartTime value > 1000000 case when migrate from DDM
                    if (newSetting.AutoStartTime != null)
                    {
                        if (newSetting.AutoStartTime > 1000000)
                            newSetting.AutoStartTime /= 10000000;
                    }

                    ddpmDesktop.ProfileSettings.Add(newSetting);
                }
                ddpmDesktops.Add(ddpmDesktop);

                idxDesktop++;
            } //foreach (Desktop ddmDesktop in ddmMonitorSettings.EasyArrangement.Desktops)

            //Save this model-ServiceTage settings to DDPM Per-Monitor model settings file
            //
            writelog($"@ DDMtoDDPM_EzArrange() - Phase IV - Save migrated Monitor settings.");

            //Read the DDPM per-model settings file
            List<DDPMMonitorSettings> modelSettings = _SettingsPlugin.ReloadMonitorSettings(model).Result;
            if (modelSettings == null)
            {
                writelog($"  * DDPM do not have the setting file of Model=[{model}]");
                modelSettings = new List<DDPMMonitorSettings>();
            }
            //Find the matched per-ServiceTag setting
            int idxThisServiceTag = modelSettings.FindIndex(x => x.ServiceTag.Equals(serviceTag));

            //If DDPM do not have this model+serviceTag monitor settings
            if (idxThisServiceTag < 0)
            {
                writelog($"  * DDPM Settings do not have the setting of Model=[{model}], ServiceTag=[{serviceTag}] => Add new.");
                DDPMMonitorSettings ddpmMonitorSettings = new DDPMMonitorSettings(); //Per-mode-serviceTag
                ddpmMonitorSettings.Model = model;
                ddpmMonitorSettings.ServiceTag = serviceTag;
                ddpmMonitorSettings.EA1 = ea1List.ToArray();

                ddpmMonitorSettings.easyArrangementDDPM = new EasyArrangementDDPM()
                {
                    Desktops = ddpmDesktops
                };

                modelSettings.Add(ddpmMonitorSettings);

                bool writeOK = _SettingsPlugin.WriteMonitorSettings(model, modelSettings).Result;

                writelog($"  * Save migrated settings Model=[{model}], ServiceTag=[{serviceTag}], Result=[{writeOK}]");
            }
            else
            {
                writelog($"  * DDPM Settings found the existing settings of Model=[{model}], ServiceTag=[{serviceTag}] => replace it.");

                modelSettings[idxThisServiceTag].EA1 = ea1List.ToArray();
                modelSettings[idxThisServiceTag].easyArrangementDDPM = new EasyArrangementDDPM()
                {
                    Desktops = ddpmDesktops
                };

                bool writeOK = _SettingsPlugin.WriteMonitorSettings(model, modelSettings).Result;

                writelog($"  * Save migrated settings Model=[{model}], ServiceTag=[{serviceTag}], Result=[{writeOK}]");
            }

            //OLD Code:
            //
            //if ((ddmMonitorSettings != null) || (ddmMonitorSettings.EasyArrangement != null))
            //{
            /*
            MonitorInfo moinfo = new MonitorInfo();
            moinfo.modelName = ddmMonitorSettings.Model;
            moinfo.edid.ModelName = ddmMonitorSettings.Model;
            moinfo.edid.ServiceTag = ddmMonitorSettings.ServiceTag;

            //Will migrate Desktop[0] only
            if (ddmMonitorSettings.EasyArrangement.Desktops.Count > 0)
            {
                //Convert ActiveLayout to SelectedSplit
                //
                int activeLayout = ddmMonitorSettings.EasyArrangement.Desktops[0].ActiveLayout;
                SplitJson? selJson = null;
                //activaLayout: [0~49]=preset layout, [1000~1004]=custom layout
                if (activeLayout >= 1000) //or EAEMConstants.EAID_FirstCustom
                {
                    //Find the CustomLayout by EAID
