        private void UpdateInstancesToPeripheralPlugin(ISettingsManagerDev SettingsInstance, IDTPProxyPlugin DTPInstance)
        {
            if (_PeripheralsPlugin != null && SettingsInstance != null)
            {
                _PeripheralsPlugin.UpdateSettingsInstance(SettingsInstance);
            }
            if (_PeripheralsPlugin != null && DTPInstance != null)
            {
                _PeripheralsPlugin.UpdateDTPInstance(DTPInstance);
            }
        }

        private void OnPeripheralOSDNotify(object sender, OSDEventArgs e)
        {
            if (e == null)
                return;
            if (string.IsNullOrEmpty(e.Requester))
                return;

            switch (e.Requester)
            {
                case "CollaborationNotAvailable.Keyboard":
                    ShowOSD(e.DeviceName, e.osd_type, e.osd_device, e.Message);
                    break;

                case "BatteryLow":
                    ShowOSD(e.DeviceName, e.osd_type, e.osd_device, e.Message, e.Guid);
                    break;

                case "Mute.Status":
                    ShowOSD(e.DeviceName, e.osd_type, e.Message, e.Status);
                    break;

                case "CloseBatteryLowOSD":
                    CloseOSD(e.osd_device, e.Guid);
                    break;

                default:
                    break;
            }
        }

        // add @ 20250116 stephen
        public Task<bool> checkDeviceConnStatus(FwRule rule)
        {
            if (!rule.devicetype.Equals("display"))
            {
                return Task.FromResult(true);
            }

            // add @ 20250204 stephen: fix no display connected in list
            if (_AllInfoMonitors.Count == 0)
            {
                return Task.FromResult(false);
            }

            bool hasModel = false;
            bool hasServiceTag = false;

            if (rule.model.Equals(string.Empty))
            {
                hasModel = true;
            }

            if (rule.servicetag.Equals(string.Empty))
            {
                hasServiceTag = true;
            }

            foreach (MonitorInfo info in _AllInfoMonitors)
            {
                if (!hasModel && info.edid.ModelName.ToLower().Equals(rule.model))
                {
                    hasModel = true;
                }

                if (!hasServiceTag && info.edid.ServiceTag.ToLower().Equals(rule.servicetag))
                {
                    hasServiceTag = true;
                    break;
                }
            }

            bool result = hasModel && hasServiceTag;

            return Task.FromResult(result);
        }

